import { ChangeDetectionStrategy, Component, DestroyRef, computed, inject, signal } from '@angular/core';
import {
  bufferTurn,
  stepSnake,
  type Direction,
  type Point
} from './snake-engine';

const BOARD_SIZE = 14;
const STEP_MS = 140;
const INITIAL_SNAKE: Point[] = [
  { x: 6, y: 7 },
  { x: 5, y: 7 },
  { x: 4, y: 7 }
];
const INITIAL_FOOD: Point = { x: 8, y: 7 };

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '(window:keydown)': 'onKeydown($event)' },
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly boardSize = BOARD_SIZE;
  readonly boardIndices = Array.from({ length: BOARD_SIZE }, (_, index) => index);

  readonly snake = signal<Point[]>(INITIAL_SNAKE.map((point) => ({ ...point })));
  readonly direction = signal<Direction>('RIGHT');
  readonly bufferedDirection = signal<Direction | null>(null);
  readonly food = signal<Point | null>({ ...INITIAL_FOOD });
  readonly isRunning = signal(false);
  readonly isGameOver = signal(false);
  readonly isWon = signal(false);
  readonly score = signal(0);

  readonly length = computed(() => this.snake().length);
  readonly statusLabel = computed(() => {
    if (this.isWon()) return 'You win';
    if (this.isGameOver()) return 'Game over';
    return this.isRunning() ? 'Running' : 'Paused';
  });

  private timerId: ReturnType<typeof setInterval> | null = null;

  constructor() {
    inject(DestroyRef).onDestroy(() => this.clearTimer());
  }

  onKeydown(event: KeyboardEvent): void {
    const key = String(event.key || '').toLowerCase();

    if (key === ' ') {
      event.preventDefault();
      if (!this.isGameOver() && !this.isWon()) this.toggleRunning();
      return;
    }

    if (key === 'enter' && (this.isGameOver() || this.isWon())) {
      event.preventDefault();
      this.reset();
      return;
    }

    const requested = this.directionFromKey(key);
    if (!requested) return;

    event.preventDefault();
    this.bufferedDirection.set(bufferTurn(this.direction(), this.bufferedDirection(), requested));
  }

  toggleRunning(): void {
    if (this.isGameOver() || this.isWon()) return;
    this.isRunning() ? this.pause() : this.start();
  }

  start(): void {
    if (this.isRunning() || this.isGameOver() || this.isWon()) return;
    this.isRunning.set(true);
    this.clearTimer();
    this.timerId = setInterval(() => this.tick(), STEP_MS);
  }

  pause(): void {
    this.isRunning.set(false);
    this.clearTimer();
  }

  reset(): void {
    this.clearTimer();
    this.snake.set(INITIAL_SNAKE.map((point) => ({ ...point })));
    this.direction.set('RIGHT');
    this.bufferedDirection.set(null);
    this.food.set({ ...INITIAL_FOOD });
    this.isRunning.set(false);
    this.isGameOver.set(false);
    this.isWon.set(false);
    this.score.set(0);
  }

  isSnake(x: number, y: number): boolean {
    return this.snake().some((point) => point.x === x && point.y === y);
  }

  isHead(x: number, y: number): boolean {
    const head = this.snake()[0];
    return head.x === x && head.y === y;
  }

  isFood(x: number, y: number): boolean {
    const food = this.food();
    return food !== null && food.x === x && food.y === y;
  }

  private tick(): void {
    if (!this.isRunning() || this.isGameOver() || this.isWon()) return;

    const result = stepSnake({
      snake: this.snake(),
      direction: this.direction(),
      bufferedDirection: this.bufferedDirection(),
      food: this.food(),
      score: this.score()
    }, this.boardSize);

    // stepSnake builds a new array for every move; editing the current array in place would not notify the signal.
    this.snake.set(result.snake);
    this.direction.set(result.direction);
    this.bufferedDirection.set(result.bufferedDirection);
    this.food.set(result.food);
    this.score.set(result.score);

    if (result.outcome === 'lost') {
      this.isGameOver.set(true);
      this.pause();
    } else if (result.outcome === 'won') {
      this.isWon.set(true);
      this.pause();
    }
  }

  private directionFromKey(key: string): Direction | null {
    if (key === 'arrowup' || key === 'w') return 'UP';
    if (key === 'arrowdown' || key === 's') return 'DOWN';
    if (key === 'arrowleft' || key === 'a') return 'LEFT';
    if (key === 'arrowright' || key === 'd') return 'RIGHT';
    return null;
  }

  private clearTimer(): void {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
  }
}
